    std::cout << "Course: " << name << " (ID: " << courseId << ")" << std::endl;
    std::cout << "Enrollment: " << getCurrentEnrollment() << "/" << maxCapacity << std::endl;
    std::cout << "Status: " << (available ? "Available" : "Closed") << std::endl;
}

