#ifndef DOUBLY_LINKED_LIST_HPP
#define DOUBLY_LINKED_LIST_HPP

template<typename K, typename V>
struct Node {
    K key;
    V value;
    Node* prev;
    Node* next;

    Node(K key, V value) : key(key), value(value), prev(nullptr), next(nullptr) {}
};

template<typename K, typename V>
class DoublyLinkedList {
private:
    Node<K,V>* head;
    Node<K,V>* tail;
    int size;

public:
    DoublyLinkedList() : head(nullptr), tail(nullptr), size(0) {}
    ~DoublyLinkedList() {
        while (head) {
            Node<K,V>* temp = head;
            head = head->next;
            delete temp;
        }
    }

    Node<K,V>* addToFront(K key, V value) {
        Node<K,V>* node = new Node<K,V>(key, value);

        if (!head) {
            head = tail = node;
        } else {
            node->next = head;
            head->prev = node;
            head = node;
        }

        size++;
        return node;
    }

    void moveToFront(Node<K,V>* node) {
        if (node == head) return;

        if (node == tail) {
            tail = node->prev;
            tail->next = nullptr;
        } else {
            node->prev->next = node->next;
            node->next->prev = node->prev;
        }

        node->prev = nullptr;
        node->next = head;
        head->prev = node;
        head = node;
    }

    void removeNode(Node<K,V>* node) {
        if (node == head) {
            head = node->next;
            if (head) head->prev = nullptr;
        } else if (node == tail) {
            tail = node->prev;
            tail->next = nullptr;
        } else {
            node->prev->next = node->next;
            node->next->prev = node->prev;
        }

        delete node;
        size--;

        if (size == 0) {
            head = tail = nullptr;
        }
    }

    Node<K,V>* removeLast() {
        if (!tail) return nullptr;

        Node<K,V>* node = tail;
        tail = tail->prev;
        if (tail) {
            tail->next = nullptr;
        } else {
            head = nullptr;
        }

        size--;
        return node;
    }

    int getSize() const { return size; }
    bool isEmpty() const { return size == 0; }
    Node<K,V>* getHead() const { return head; }
    Node<K,V>* getTail() const { return tail; }
};

#endif

#ifndef LRU_CACHE_HPP
#define LRU_CACHE_HPP

#include <unordered_map>
#include "DoublyLinkedList.hpp"

template<typename K, typename V>
class LRUCache {
private:
    int capacity;
    DoublyLinkedList<K,V> dll;
    std::unordered_map<K, Node<K,V>*> cache;

public:
    LRUCache(int capacity) : capacity(capacity) {}

    V get(K key) {
        auto it = cache.find(key);
        if (it == cache.end()) {
            throw std::runtime_error("Key not found");
        }

        Node<K,V>* node = it->second;
        dll.moveToFront(node);
        return node->value;
    }

    void put(K key, V value) {
        auto it = cache.find(key);
        if (it != cache.end()) {
            // Key exists, update value and move to front
            Node<K,V>* node = it->second;
            node->value = value;
            dll.moveToFront(node);
        } else {
            // Key doesn't exist, add new entry
            if (cache.size() >= capacity) {
                // Remove least recently used item
                Node<K,V>* lastNode = dll.getTail();
                cache.erase(lastNode->key);
                dll.removeNode(lastNode);
            }

            // Add new item to front
            Node<K,V>* newNode = dll.addToFront(key, value);
            cache[key] = newNode;
        }
    }

    bool contains(K key) const {
        return cache.find(key) != cache.end();
    }

    int getSize() const {
        return cache.size();
    }

    bool isEmpty() const {
        return cache.empty();
    }

    void clear() {
        while (!dll.isEmpty()) {
            Node<K,V>* node = dll.removeLast();
            cache.erase(node->key);
            delete node;
        }
    }

    void display() const {
        std::cout << "\nLRU Cache Contents:" << std::endl;
        Node<K,V>* current = dll.getHead();
        while (current) {
            std::cout << current->key << " -> " << current->value << std::endl;
            current = current->next;
        }
        std::cout << "Cache size: " << cache.size() << "/" << capacity << std::endl;
    }
};

#endif

#include "LRUCache.hpp"
#include <iostream>
#include <string>

int main() {
    // Create LRU cache with capacity 3
    LRUCache<int, std::string> cache(3);

    // Add some entries
    std::cout << "Adding entries to cache..." << std::endl;
    cache.put(1, "One");
    cache.put(2, "Two");
    cache.put(3, "Three");
    cache.display();

    // Try to get an entry
    std::cout << "\nGetting value for key 2..." << std::endl;
    std::cout << "Value: " << cache.get(2) << std::endl;
    cache.display();  // 2 should move to front

    // Add new entry when cache is full
    std::cout << "\nAdding new entry when cache is full..." << std::endl;
    cache.put(4, "Four");  // Should evict least recently used item
    cache.display();

    // Try to access non-existent key
    std::cout << "\nTrying to access non-existent key..." << std::endl;
    try {
        cache.get(1);  // Should throw exception
    } catch (const std::runtime_error& e) {
        std::cout << "Error: " << e.what() << std::endl;
    }

    // Update existing entry
    std::cout << "\nUpdating existing entry..." << std::endl;
    cache.put(2, "Two Updated");
    cache.display();

    // Clear cache
    std::cout << "\nClearing cache..." << std::endl;
    cache.clear();
    cache.display();

    return 0;
}

