    std::cout << "Status: " << (accepted ? "Accepted" : "Not Accepted") << std::endl;

    if (!tags.empty()) {
        std::cout << "Tags: ";
        for (const auto& tag : tags) {
            std::cout << tag << " ";
        }
        std::cout << std::endl;
    }

    if (!comments.empty()) {
        std::cout << "Comments:" << std::endl;
        for (const auto& comment : comments) {
            comment->displayInfo();
        }
    }

    std::cout << "Time: " << std::ctime(&timestamp);
}

