                Console.WriteLine("Transaction ID: " + transaction.GetId());
                Console.WriteLine("Amount: " + transaction.GetAmount() + " " + transaction.GetCurrency());
                Console.WriteLine("Timestamp: " + transaction.GetTimestamp());
                Console.WriteLine();
