}

func (k *King) CanMove(board *Board, destRow, destCol int) bool {
	rowDiff := math.Abs(float64(destRow - k.row))
	colDiff := math.Abs(float64(destCol - k.col))
	return rowDiff <= 1 && colDiff <= 1
}

