package votingsystem;

import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.locks.ReadWriteLock;
import java.util.concurrent.locks.ReentrantReadWriteLock;

public class VotingSystem {
    private static volatile VotingSystem instance;
    private final Map<String, Voter> voters;
    private final Map<String, Candidate> candidates;
    private final Map<String, AtomicInteger> voteCount;
    private final Set<String> votedVoters;
    private final ReadWriteLock votingLock;
    private volatile boolean isVotingOpen;
    private final BlockingQueue<VoteRecord> voteAuditLog;

    private VotingSystem() {
        this.voters = new ConcurrentHashMap<>();
        this.candidates = new ConcurrentHashMap<>();
        this.voteCount = new ConcurrentHashMap<>();
        this.votedVoters = ConcurrentHashMap.newKeySet();
        this.votingLock = new ReentrantReadWriteLock();
        this.voteAuditLog = new LinkedBlockingQueue<>();
        this.isVotingOpen = false;
    }

    public static VotingSystem getInstance() {
        VotingSystem result = instance;
        if (result == null) {
            synchronized (VotingSystem.class) {
                if (result == null) {
                    instance = result = new VotingSystem();
                }
            }
        }
        return result;
    }

    public void registerVoter(String voterId, String name, String password) {
        Voter voter = new Voter(voterId, name, password);
        voters.putIfAbsent(voterId, voter);
    }

    public void registerCandidate(String candidateId, String name, String party) {
        Candidate candidate = new Candidate(candidateId, name, party);
        candidates.putIfAbsent(candidateId, candidate);
        voteCount.putIfAbsent(candidateId, new AtomicInteger(0));
    }

    public void startVoting() {
        votingLock.writeLock().lock();
        try {
            isVotingOpen = true;
            System.out.println("Voting has started!");
        } finally {
            votingLock.writeLock().unlock();
        }
    }

    public void endVoting() {
        votingLock.writeLock().lock();
        try {
            isVotingOpen = false;
            System.out.println("Voting has ended!");
        } finally {
            votingLock.writeLock().unlock();
        }
    }

    public boolean castVote(String voterId, String candidateId) {
        votingLock.readLock().lock();
        try {
            if (!isVotingOpen) {
                System.out.println("Voting is not open!");
                return false;
            }

            Voter voter = voters.get(voterId);
            Candidate candidate = candidates.get(candidateId);
            
            if (voter == null || candidate == null) {
                System.out.println("Invalid voter or candidate ID!");
                return false;
            }

            if (!votedVoters.add(voterId)) {
                System.out.println("Voter has already cast their vote!");
                return false;
            }

            voteCount.get(candidateId).incrementAndGet();
            
            voteAuditLog.offer(new VoteRecord(voterId, candidateId, System.currentTimeMillis()));
            
            return true;
        } finally {
            votingLock.readLock().unlock();
        }
    }

    public Map<String, Integer> getCurrentResults() {
        Map<String, Integer> results = new HashMap<>();
        votingLock.readLock().lock();
        try {
            for (Map.Entry<String, AtomicInteger> entry : voteCount.entrySet()) {
                results.put(candidates.get(entry.getKey()).getName(), 
                           entry.getValue().get());
            }
            return results;
        } finally {
            votingLock.readLock().unlock();
        }
    }

    public List<VoteRecord> getAuditLog() {
        return new ArrayList<>(voteAuditLog);
    }
}

package votingsystem;

import java.util.*;
import java.util.concurrent.*;

public class VotingSystemDemo {
    public static void run() {
        VotingSystem votingSystem = VotingSystem.getInstance();

        votingSystem.registerCandidate("C1", "John Doe", "Party A");
        votingSystem.registerCandidate("C2", "Jane Smith", "Party B");

        for (int i = 1; i <= 100; i++) {
            votingSystem.registerVoter("V" + i, "Voter " + i, "pass" + i);
        }

        votingSystem.startVoting();

        ExecutorService executor = Executors.newFixedThreadPool(10);
        List<Future<Boolean>> futures = new ArrayList<>();

        for (int i = 1; i <= 100; i++) {
            final String voterId = "V" + i;
            final String candidateId = "C" + ((i % 2) + 1);

            futures.add(executor.submit(() -> {
                try {
                    Thread.sleep(new Random().nextInt(100));
                    return votingSystem.castVote(voterId, candidateId);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    return false;
                }
            }));
        }

        for (Future<Boolean> future : futures) {
            try {
                future.get();
            } catch (Exception e) {
                e.printStackTrace();
            }
        }

        votingSystem.endVoting();

        Map<String, Integer> results = votingSystem.getCurrentResults();
        System.out.println("\nVoting Results:");
        results.forEach((candidate, votes) -> 
            System.out.println(candidate + ": " + votes + " votes"));

        System.out.println("\nAudit Log:");
        votingSystem.getAuditLog().forEach(System.out::println);

        executor.shutdown();
    }
}

package coffeevendingmachine;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.DisplayName;

import static org.junit.jupiter.api.Assertions.*;

import java.io.ByteArrayOutputStream;
import java.io.PrintStream;
import java.util.Map;

public class CoffeeVendingMachineTest {

    private CoffeeVendingMachine machine;
    private final ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
    private final PrintStream originalOut = System.out;

    @BeforeEach
    void setUp() {
        machine = CoffeeVendingMachine.getInstance();
        System.setOut(new PrintStream(outputStream));

        // Reset and refill ingredients for each test
        machine.refillIngredient("Water", 150);
        machine.refillIngredient("Coffee", 100);
        machine.refillIngredient("Milk", 100);
    }

    @Test
    @DisplayName("Test coffee selection")
    void testSelectCoffee() {
        CoffeeRecipe espresso = machine.selectCoffee("Espresso");
        assertEquals("Espresso", espresso.getName());
        assertEquals(2.5, espresso.getPrice());
        assertEquals(50, espresso.getRecipe().get("Water"));
        assertEquals(20, espresso.getRecipe().get("Coffee"));
    }

    @Test
    @DisplayName("Test invalid coffee selection")
    void testInvalidCoffeeSelection() {
        Exception exception = assertThrows(RuntimeException.class, () -> {
            machine.selectCoffee("MochaCoffee");
        });

        String expectedMessage = "Invalid coffee recipe: MochaCoffee";
        String actualMessage = exception.getMessage();

        assertTrue(actualMessage.contains(expectedMessage));
    }

    @Test
    @DisplayName("Test successful coffee dispensing")
    void testDispenseCoffee() {
        CoffeeRecipe latte = machine.selectCoffee("Latte");
        machine.dispenseCoffee(latte, new Payment(4.0));

        String output = outputStream.toString();
        assertTrue(output.contains("Dispensing: Latte"));
        assertTrue(output.contains("Processing Payment"));
        assertTrue(output.contains("Please collect your change: $1.0"));
    }

    @Test
    @DisplayName("Test insufficient payment")
    void testInsufficientPayment() {
        CoffeeRecipe cappuccino = machine.selectCoffee("Cappuccino");

        Exception exception = assertThrows(RuntimeException.class, () -> {
            machine.dispenseCoffee(cappuccino, new Payment(2.0));
        });

        String expectedMessage = "Insufficient payment for Cappuccino";
        String actualMessage = exception.getMessage();

        assertTrue(actualMessage.contains(expectedMessage));
    }



    @Test
    @DisplayName("Test ingredient consumption")
    void testIngredientConsumption() {
        CoffeeRecipe latte = machine.selectCoffee("Latte");

        // Check initial levels
        Map<String, Integer> beforeLevels = machine.showIngredientsMap();
        int initialWaterLevel = beforeLevels.get("Water");
        int initialCoffeeLevel = beforeLevels.get("Coffee");
        int initialMilkLevel = beforeLevels.get("Milk");

        machine.dispenseCoffee(latte, new Payment(3.0));

        // Check levels after dispensing
        Map<String, Integer> afterLevels = machine.showIngredientsMap();
        assertEquals(initialWaterLevel - 50, afterLevels.get("Water").intValue());
        assertEquals(initialCoffeeLevel - 20, afterLevels.get("Coffee").intValue());
        assertEquals(initialMilkLevel - 30, afterLevels.get("Milk").intValue());
    }

    @Test
    @DisplayName("Test ingredient refill")
    void testIngredientRefill() {
        // First check initial level
        Map<String, Integer> beforeLevels = machine.showIngredientsMap();
        int initialWaterLevel = beforeLevels.get("Water");

        // Add more water
        machine.refillIngredient("Water", 50);

        // Check after refill
        Map<String, Integer> afterLevels = machine.showIngredientsMap();
        assertEquals(initialWaterLevel + 50, afterLevels.get("Water").intValue());
    }
}

